def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    def get_factors(n: int, factor: int):
        """Yield all prime factors of n starting from factor."""
        while n % factor == 0:
            yield factor
            n //= factor
        next_factor = factor + 1 if factor == 2 else factor * 2
        while next_factor * next_factor <= n:
            if n % next_factor == 0:
                yield from get_factors(n, next_factor)
            next_factor += 2
        if n > 1:
            yield n

    factors = list(get_factors(n, 2))
    return max(factors)

