    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    min_heap = []

    for i in range(n):
        for j in range(n):
            for dx, dy in directions:
                x, y = i, j
                path = [grid[i][j]]
                steps = 1
                while steps < k:
                    x += dx
                    y += dy
                    if 0 <= x < n and 0 <= y < n:
