from heapq import heappush, heappop

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right
    min_path = []

    def in_bounds(x, y):
        return 0 <= x < N and 0 <= y < N

    def get_neighbors(x, y):
        neighbors = []
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if in_bounds(nx, ny):
                neighbors.append((nx, ny))
        return neighbors

    def dijkstra(start_x, start_y):
        pq = []
        heappush(pq, (grid[start_x][start_y], start_x, start_y, [grid[start_x][start_y]]))
        visited = set()

        while pq:
            path_val, x, y, path = heappop(pq)

            if len(path) == k:
                min_path.extend(path)
